document.addEventListener('DOMContentLoaded', () => {
  document.addEventListener('click', (e) => {
    if (e.target.closest('a, input[type="file"]')) e.preventDefault();
  });
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Tab' && e.target.closest('a, input[type="file"]')) e.preventDefault();
  });
  document.addEventListener('submit', (e) => { e.preventDefault(); });
  const assets = globalThis.__atlasAssets;
  if (!assets) return;
  document.querySelectorAll('[data-atlas-asset]').forEach((el) => {
    const key = el.getAttribute('data-atlas-asset');
    const url = key && assets[key];
    if (!url) return;
    if (el.hasAttribute('src')) el.setAttribute('src', url);
    if (el.hasAttribute('srcset')) el.setAttribute('srcset', url);
    if (el.hasAttribute('poster')) el.setAttribute('poster', url);
  });
});
